import numpy as np


def _tokenize(text):
    # sklearn default: lowercase, then r"(?u)\b\w\w+\b" (word chars, length >= 2)
    tokens = []
    word = []
    for ch in text.lower():
        if ch.isalnum() or ch == "_":
            word.append(ch)
        else:
            if len(word) >= 2:
                tokens.append("".join(word))
            word = []
    if len(word) >= 2:
        tokens.append("".join(word))
    return tokens


class MyTfidf:
    def __init__(self):
        self.vocabulary_ = {}
        self.idf_ = None

    def _count(self, raw_documents):
        vocab = self.vocabulary_
        rows = []
        for doc in raw_documents:
            counts = {}
            for tok in _tokenize(doc):
                counts[tok] = counts.get(tok, 0) + 1
            row = {vocab[t]: c for t, c in counts.items() if t in vocab}
            rows.append(row)
        return rows

    def fit(self, raw_documents):
        # Build vocabulary in order of first occurrence (sklearn convention).
        vocab = {}
        for doc in raw_documents:
            for tok in _tokenize(doc):
                if tok not in vocab:
                    vocab[tok] = len(vocab)

        n_docs = len(raw_documents)
        df = np.zeros(len(vocab))
        for doc in raw_documents:
            for tok in set(_tokenize(doc)):
                df[vocab[tok]] += 1

        # Smooth idf: ln((1+n)/(1+df)) + 1
        self.idf_ = np.log((1.0 + n_docs) / (1.0 + df)) + 1.0
        self.vocabulary_ = vocab

        X = np.zeros((n_docs, len(vocab)))
        for i, row in enumerate(self._count(raw_documents)):
            for j, c in row.items():
                X[i, j] = c

        # L2 normalize each row.
        norms = np.sqrt(np.sum(X * X, axis=1))
        nonzero = norms > 0
        X[nonzero] /= norms[nonzero][:, None]
        return self._last_transform = X

    def transform(self, raw_documents):
        X = np.zeros((len(raw_documents), len(self.vocabulary_)))
        for i, row in enumerate(self._count(raw_documents)):
            for j, c in row.items():
                X[i, j] = c * self.idf_[j]
        norms = np.sqrt(np.sum(X * X, axis=1))
        nonzero = norms > 0
        X[nonzero] /= norms[nonzero][:, None]
        return X

    def fit_transform(self, raw_documents):
        self.fit(raw_documents)
        return self.transform(raw_documents)

